33	/** Basic URL validation — checks structure, not reachability */
34	function isValidUrl(str: string): boolean {
35	  try {
36	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
37	    return url.protocol === "https:" || url.protocol === "http:";
38	  } catch {
39	    return false;
40	  }
41	}
42	
43	/** Normalize URL: prepend https:// if missing */
44	function normalizeUrl(str: string): string {
45	  const trimmed = str.trim();
46	  if (!trimmed) return trimmed;
47	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
48	  return `https://${trimmed}`;
49	}
