85	
86	  const filtered = useMemo(() => {
87	    let list = [...scans];
88	
89	    // Search — matches URL, hostname, and page title
90	    if (search) {
91	      const q = search.toLowerCase();
92	      list = list.filter(
93	        (s) =>
