12	 *
13	 * Supabase sends a PKCE code in the URL fragment (#access_token=...) or as
14	 * a query param (?code=...) depending on the flow. The Supabase JS client
15	 * resolves this automatically via onAuthStateChange with event "PASSWORD_RECOVERY".
16	 * We listen for that event to know when the recovery session is active, then
17	 * allow the user to set a new password.
18	 */
19	
20	type PageState = "loading" | "form" | "success" | "invalid";
21	
22	const ResetPassword = () => {
23	  const navigate = useNavigate();
24	
25	  const [pageState, setPageState] = useState<PageState>("loading");
26	  const [password, setPassword] = useState("");
27	  const [confirmPassword, setConfirmPassword] = useState("");
28	  const [showPassword, setShowPassword] = useState(false);
29	  const [showConfirm, setShowConfirm] = useState(false);
30	  const [submitting, setSubmitting] = useState(false);
31	
32	  useEffect(() => {
33	    // If Supabase sent a PKCE code in the URL (?code=...), getSession will
34	    // exchange it and fire PASSWORD_RECOVERY.  We also listen for
35	    // SIGNED_IN which Supabase emits on code exchange in newer SDK versions.
36	    const {
37	      data: { subscription },
38	    } = supabase.auth.onAuthStateChange((event) => {
39	      if (event === "PASSWORD_RECOVERY") {
40	        setPageState("form");
41	      }
42	    });
43	
44	    // Kick off session resolution — handles both hash-based and code-based flows.
45	    supabase.auth.getSession().then(({ data: { session } }) => {
46	      // If a session already exists (user is already logged in and followed the
47	      // link), show the form directly.
48	      if (session) {
49	        setPageState("form");
50	      } else {
51	        // Give the onAuthStateChange listener 3 seconds to fire before marking
52	        // the link as invalid.
53	        const timer = setTimeout(() => {
54	          setPageState((current) =>
55	            current === "loading" ? "invalid" : current
56	          );
57	        }, 3000);
58	        return () => clearTimeout(timer);
59	      }
60	    });
61	
62	    return () => subscription.unsubscribe();
63	  }, []);
